/// Bytes-in → snapshot-out. Delegates to `svc_core::engine::snapshot_files`.
pub(crate) fn snapshot_files(
    &self,
    files: &BTreeMap<RelPath, Vec<u8>>,
    prev: Option<&Snapshot>,
    change: ChangeId,
) -> Result<Snapshot> {
    // Files whose bytes are what `prev` rendered keep `prev`'s records when the tree's
    // definitions are unchanged: an absorb of one file no longer re-materializes all.
    let unchanged: std::collections::BTreeSet<RelPath> = match prev.and_then(|p| self.store.rendered_hashes(p.id()).ok().flatten()) {
        Some(hashes) => files
            .iter()
            .filter(|(path, bytes)| hashes.get(*path) == Some(blake3::hash(bytes).as_bytes()))
            .map(|(path, _)| path.clone())
            .collect(),
        None => Default::default(),
    };
    svc_core::engine::snapshot_files_reusing(&self.store, &self.langs, files, prev, change, &unchanged)
}

crates/svc-repo/src/repo.rs.Text:
//! A checked-out repository: the `.svc/` store plus the working copy around it.
//!
//! Every mutating verb goes through [`Repo::mutate`], which snapshots the working copy
//! before, commits, records the op, and renders after. Nothing here decides
//! what a snapshot *contains* — that is `svc_core::engine`'s job; this module only moves
//! bytes between disk and store and keeps `root`/`heads`/the op log consistent.

use std::collections::{BTreeMap, BTreeSet};
use std::fs::{File, OpenOptions};
use std::io::{ErrorKind, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use svc_core::engine::{render, snapshot_files as engine_snapshot_files};
use svc_core::{
    CHANGESET_TTL_MS, ChangeId, ChangeSetId, Error, JsLang, Langs, ObservedClass, Op, OpIx,
    OpLogEntry, RelPath, Result, RustLang, Snapshot, SnapshotId, Store, Timestamp, View,
};

use crate::store::RedbStore;
use crate::workspace::{POINTER_FILE, WorkspacePointer};

pub const STORE_DIR: &str = ".svc";
pub const STORE_FILE: &str = "store.redb";
/// The store while `init` imports; renamed to [`STORE_FILE`] once the first op is in.
pub const STORE_FILE_IMPORTING: &str = "store.redb.importing";
pub const IGNORE_FILE: &str = ".svcignore";
/// Under `.svc/`: held (`flock`) by the one `Repo` open on the default checkout.
pub const CHECKOUT_LOCK: &str = "checkout.lock";

/// Directories never walked, on top of `.svcignore`.
const ALWAYS_IGNORED: &[&str] = &[
    STORE_DIR,
    ".git",
    ".jj",
    "target",
    "node_modules",
    POINTER_FILE,
];

/// How long `open` waits for another `svc` process to leave this checkout unless
/// `SVC_LOCK_TIMEOUT_MS` or [`Repo::open_with`] says otherwise.
///
/// The store is shared: any number of processes hold it open (redb `MultiWriter`), write
/// transactions serialise on the file, readers follow commits, and a publish that finds a
/// head or this checkout's root moved since the verb read them is refused with nothing
/// written (`append_op`). The working copy is not shared: one `Repo` per checkout at a
/// time, held by a lock on [`CHECKOUT_LOCK`] (a named checkout's pointer file doubles as
/// its lock), so two `svc` processes never render into one directory at once.
pub const DEFAULT_LOCK_TIMEOUT: Duration = Duration::from_secs(5);
pub const LOCK_TIMEOUT_ENV: &str = "SVC_LOCK_TIMEOUT_MS";

pub fn lock_timeout() -> Duration {
    std::env::var(LOCK_TIMEOUT_ENV)
        .ok()
        .and_then(|v| v.trim().parse::<u64>().ok())
        .map(Duration::from_millis)
        .unwrap_or(DEFAULT_LOCK_TIMEOUT)
}

pub struct Repo {
    root: PathBuf,
    store_path: PathBuf,
    pub(crate) store: RedbStore,
    langs: Langs,
    _checkout_lock: File,
    /// Set while a history is replayed: the op line takes the recorded time, changeset and
    /// checkout instead of now, the open changeset and this checkout.
    provenance: Mutex<Option<Provenance>>,
}

/// Where an op line came from, when it did not come from this process now.
#[derive(Clone, Debug)]
pub struct Provenance {
    pub at: Timestamp,
    pub group: Option<ChangeSetId>,
    /// The checkout that made it (`None` = the default one).
    pub workspace: Option<String>,
}

/// What `mutate` did, for the verb to print.
#[derive(Clone, Debug)]
pub struct Mutation {
    pub ix: OpIx,
    pub entry: OpLogEntry,
    /// The snapshot the op produced (equal to `entry.after.root` unless the op was a no-op).
    pub snapshot: SnapshotId,
    /// Set when a stale `open_changeset` row was closed on the way.
    pub closed_stale_changeset: Option<ChangeSetId>,
}

impl Repo {
    pub fn default_langs() -> Langs {
        Langs::new(vec![Box::new(RustLang), Box::new(JsLang)])
    }

    /// Nearest ancestor of `start` (inclusive) that is a checkout: it holds `.svc/store.redb`
    /// (the default checkout) or a `.svc-workspace` pointer (a named one).
    pub fn find_root(start: &Path) -> Option<PathBuf> {
        start
            .ancestors()
            .find(|p| Self::is_checkout(p))
            .map(Path::to_path_buf)
    }

    fn is_checkout(dir: &Path) -> bool {
        dir.join(STORE_DIR).join(STORE_FILE).is_file() || dir.join(POINTER_FILE).is_file()
    }

    /// Creates `.svc/` and the first snapshot from every tracked file. Refuses to re-init.
    ///
    /// The store is born as [`STORE_FILE_IMPORTING`] and renamed to [`STORE_FILE`] only after
    /// the first op has committed, so a killed or failed import never leaves a directory
    /// that looks like a checkout but has no root: until the rename it is not a checkout,
    /// and the next `init` sweeps the leftover.
    pub fn init(root: &Path, langs: Langs) -> Result<Self> {
        let dir = root.join(STORE_DIR);
        if dir.join(STORE_FILE).exists() {
            return Err(Error::Other(format!("{} already exists", dir.display())));
        }
        if root.join(POINTER_FILE).exists() {
            return Err(Error::Other(format!(
                "{} is already a workspace of another store",
                root.display()
            )));
        }
        std::fs::create_dir_all(&dir).map_err(Error::backend)?;
        let made = Self::first_import(root, &dir, langs);
        if made.is_err() {
            let _ = std::fs::remove_file(dir.join(STORE_FILE_IMPORTING));
            let _ = std::fs::remove_file(dir.join(CHECKOUT_LOCK));
            let _ = std::fs::remove_dir(&dir);
        }
        made
    }

    fn first_import(root: &Path, dir: &Path, langs: Langs) -> Result<Self> {
        let checkout_lock = Self::checkout_lock(&dir.join(CHECKOUT_LOCK), lock_timeout())?;
        let importing = dir.join(STORE_FILE_IMPORTING);
        // A previous init died mid-import; the lock says nobody is in it now.
        let _ = std::fs::remove_file(&importing);
        let store = RedbStore::create(&importing)?;
        let mut repo = Self {
            root: root.to_path_buf(),
            store_path: importing.clone(),
            store,
            langs,
            _checkout_lock: checkout_lock,
            provenance: Mutex::new(None),
        };
        let change = ChangeId::new();
        // Every blob and snapshot of the first import lands in the one transaction that
        // records the op: one fsync, and no half-imported store on a crash.
        repo.store.stage(None);
        let files = repo.tracked_files()?;
        let snapshot = repo.snapshot_files(&files, None, change)?;
        // The op log needs a "before"; an empty snapshot makes init blame as `Added`.
        let empty = repo.store.put_snapshot(&Snapshot {
            entities: BTreeMap::new(),
            files: BTreeMap::new(),
            ..snapshot.clone()
        })?;
        repo.commit_snapshot(&snapshot)?;
        let view = repo.view()?;
        repo.store.append_op(&OpLogEntry {
            op: Op::New { change },
            observed: None,
            at: now(),
            group: None,
            before: View {
                root: empty,
                heads: BTreeMap::new(),
            },
            after: view,
        })?;
        let store_path = dir.join(STORE_FILE);
        std::fs::rename(&importing, &store_path).map_err(Error::backend)?;
        repo.store_path = store_path;
        Ok(repo)
    }

    /// Opens an existing repo, waiting out another process on the same checkout, and finishes
    /// any render a crashed predecessor left pending.
    ///
    /// `root` is either the default checkout (holds `.svc/store.redb`) or a named workspace
    /// (holds a `.svc-workspace` pointer at the shared store).
    pub fn open(root: &Path, langs: Langs) -> Result<Self> {
        Self::open_with(root, langs, lock_timeout())
    }

    /// [`Repo::open`] with an explicit bound on how long to wait for another session on this
    /// checkout.
    pub fn open_with(root: &Path, langs: Langs, wait: Duration) -> Result<Self> {
        let own = root.join(STORE_DIR).join(STORE_FILE);
        let (store_path, workspace) = if own.is_file() {
            (own, None)
        } else if let Some(ptr) = WorkspacePointer::read(root)? {
            (ptr.store, Some(ptr.name))
        } else {
            return Err(Error::Other(format!("no {STORE_DIR} in {}", root.display())));
        };
        if !store_path.is_file() {
            return Err(Error::Other(format!(
                "{} points at a missing store {}",
                root.join(POINTER_FILE).display(),
                store_path.display()
            )));
        }
        let lock_path = match workspace {
            Some(_) => root.join(POINTER_FILE),
            None => root.join(STORE_DIR).join(CHECKOUT_LOCK),
        };
        let checkout_lock = Self::checkout_lock(&lock_path, wait)?;
        let store = RedbStore::open(&store_path)?.with_workspace(workspace.as_deref())?;
        // A store written before the current snapshot encoding does not decode; say so
        // rather than surfacing the decoder's complaint.
        if let Err(e) = store.root().and_then(|root| store.get_snapshot(root)) {
            return Err(Error::Other(format!(
                "{} was written by an older svc and cannot be read by this one ({e}); on a clean tree: rm -rf .svc && svc init (secondary checkouts: svc workspace add again)",
                store_path.display()
            )));
        }
        // A pointer names a workspace; only the directory the store registered for that
        // name is its working copy. Anything else opened as it would absorb its own files
        // into that change.
        if let Some(name) = &workspace {
            let registered = store.workspace_row(name)?.map(|r| r.path).unwrap_or_default();
            let here = root.canonicalize().map_err(Error::backend)?;
            if registered != here {
                return Err(Error::Other(format!(
                    "{} names workspace {name:?}, which is registered at {}; this directory is not that checkout",
                    root.join(POINTER_FILE).display(),
                    registered.display()
                )));
            }
        }
        let repo = Self {
            root: root.to_path_buf(),
            store_path,
            store,
            langs,
            _checkout_lock: checkout_lock,
            provenance: Mutex::new(None),
        };
        if repo.store.render_pending()? {
            repo.render_to_disk(&repo.current()?)?;
            repo.store.set_render_pending(false)?;
        }
        Ok(repo)
    }

    /// Takes the checkout's lock, polling up to `wait` while another `svc` holds it. The
    /// kernel drops it with the process, so a crash never leaves a checkout locked.
    fn checkout_lock(path: &Path, wait: Duration) -> Result<File> {
        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(path)
            .map_err(Error::backend)?;
        let started = Instant::now();
        let mut backoff = Duration::from_millis(10);
        loop {
            match file.try_lock() {
                Ok(()) => return Ok(file),
                Err(std::fs::TryLockError::WouldBlock) => {
                    if started.elapsed() >= wait {
                        return Err(Error::Other(format!(
                            "checkout busy: another svc session held {} for {}ms (raise {LOCK_TIMEOUT_ENV})",
                            path.display(),
                            wait.as_millis()
                        )));
                    }
                    std::thread::sleep(backoff);
                    backoff = (backoff * 2).min(Duration::from_millis(250));
                }
                Err(std::fs::TryLockError::Error(e)) => return Err(Error::backend(e)),
            }
        }
    }

    /// True when this checkout's `root` is no longer its change's head — another checkout
    /// (or `svc checkout` of an older evolution) moved on. Mutating from here would silently
    /// overwrite that head, so [`Repo::mutate`] refuses until `workspace::update_stale`.
    pub fn is_stale(&self) -> Result<bool> {
        let cur = self.current()?;
        Ok(self.store.head(cur.change)? != cur.id())
    }

    fn refuse_if_stale(&self) -> Result<()> {
        if self.is_stale()? {
            let cur = self.current()?;
            return Err(Error::Other(format!(
                "checkout is behind change {}: its head moved to {} (run `svc workspace update-stale`, or `svc checkout` it)",
                cur.change.short(),
                self.store.head(cur.change)?.short()
            )));
        }
        Ok(())
    }

    pub fn discover(start: &Path, langs: Langs) -> Result<Self> {
        let Some(root) = Self::find_root(start) else {
            let unfinished = start
                .ancestors()
                .find(|p| p.join(STORE_DIR).join(STORE_FILE_IMPORTING).is_file());
            return Err(Error::Other(match unfinished {
                Some(p) => format!(
                    "{} holds an unfinished import (an svc init that did not finish); run svc init again",
                    p.join(STORE_DIR).display()
                ),
                None => format!("no {STORE_DIR} above {}", start.display()),
            }));
        };
        Self::open(&root, langs)
    }

    pub fn store(&self) -> &dyn Store {
        &self.store
    }

    /// The concrete store, for what the `Store` trait does not cover (workspaces, op attribution).
    /// Run `f` with every op it records stamped as `p` (a replayed history keeps its times,
    /// changesets and checkouts); cleared afterwards, also on error.
    pub fn with_provenance<T>(&self, p: Provenance, f: impl FnOnce() -> Result<T>) -> Result<T> {
        *self.provenance.lock().unwrap() = Some(p);
        let out = f();
        *self.provenance.lock().unwrap() = None;
        out
    }

    /// Time and changeset for the op line being written: the provenance if one is set, else
    /// now and the open changeset (closing a stale one on the way).
    fn stamp(&self) -> Result<(Timestamp, Option<ChangeSetId>, Option<ChangeSetId>)> {
        if let Some(p) = self.provenance.lock().unwrap().as_ref() {
            return Ok((p.at, p.group, None));
        }
        let (group, closed) = self.open_group()?;
        Ok((now(), group, closed))
    }

    fn append_op(&self, entry: &OpLogEntry) -> Result<OpIx> {
        let ws = self.provenance.lock().unwrap().as_ref().and_then(|p| p.workspace.clone());
        match ws {
            Some(w) => self.store.append_op_as(entry, Some(&w)),
            None if self.provenance.lock().unwrap().is_some() => self.store.append_op_as(entry, None),
            None => self.store.append_op(entry),
        }
    }

    pub fn redb(&self) -> &RedbStore {
        &self.store
    }

    pub fn root_dir(&self) -> &Path {
        &self.root
    }

    /// The shared `.svc/store.redb` this checkout reads, wherever the checkout itself lives.
    pub fn store_path(&self) -> &Path {
        &self.store_path
    }

    /// The named workspace this checkout is, or `None` for the default one.
    pub fn workspace(&self) -> Option<&str> {
        self.store.workspace()
    }

    pub fn langs(&self) -> &Langs {
        &self.langs
    }

    pub fn view(&self) -> Result<View> {
        Ok(View {
            root: self.store.root()?,
            heads: self.store.heads()?.into_iter().collect(),
        })
    }

    /// The working-copy snapshot and its id.
    pub fn current(&self) -> Result<Snapshot> {
        self.store.get_snapshot(self.store.root()?)
    }

    pub fn current_change(&self) -> Result<ChangeId> {
        Ok(self.current()?.change)
    }

    /// Branch name first, then unique change-id prefix.
    pub fn resolve_change(&self, s: &str) -> Result<ChangeId> {
        if let Some(id) = self.store.branch(s)? {
            return Ok(id);
        }
        self.store.resolve_prefix(s)
    }

    /// Every file under the root that is not ignored. Language files become entities;
    /// everything else is an opaque `FileRecord` (Cargo.toml, lockfiles, …) so a
    /// render of this repository is still a crate cargo can build.
    /// Regular files only: symlinks (dangling or not, to files or to directories), FIFOs,
    /// sockets and devices are not tracked — a store holds bytes, and reading a FIFO would
    /// block every verb.
    pub fn tracked_files(&self) -> Result<BTreeMap<RelPath, Vec<u8>>> {
        let ignore = self.ignore_patterns()?;
        let mut out = BTreeMap::new();
        let mut stack = vec![self.root.clone()];
        while let Some(dir) = stack.pop() {
            for entry in std::fs::read_dir(&dir).map_err(Error::backend)? {
                let entry = entry.map_err(Error::backend)?;
                let path = entry.path();
                let rel_os = path.strip_prefix(&self.root).map_err(|e| Error::Other(e.to_string()))?;
                let lossy = rel_os.to_string_lossy();
                if is_ignored(&lossy, &ignore) {
                    continue;
                }
                // A store path is a string; a name it cannot hold would come back changed
                // from a render, so it is refused here by name instead.
                let Some(rel) = rel_os.to_str().map(str::to_owned) else {
                    return Err(Error::InvalidPath(format!(
                        "{lossy}: file name is not UTF-8; rename it, or ignore its directory in {IGNORE_FILE}"
                    )));
                };
                let kind = entry.file_type().map_err(Error::backend)?;
                if kind.is_dir() {
                    stack.push(path);
                    continue;
                }
                if !kind.is_file() {
                    continue;
                }
                let rel = RelPath::new(rel).map_err(Error::InvalidPath)?;
                out.insert(rel, std::fs::read(&path).map_err(Error::backend)?);
            }
        }
        Ok(out)
    }

    fn ignore_patterns(&self) -> Result<Vec<String>> {
        let mut pats: Vec<String> = ALWAYS_IGNORED.iter().map(|s| s.to_string()).collect();
        if let Ok(text) = std::fs::read_to_string(self.root.join(IGNORE_FILE)) {
            pats.extend(
                text.lines()
                    .map(str::trim)
                    .filter(|l| !l.is_empty() && !l.starts_with('#'))
                    .map(|l| l.trim_end_matches('/').trim_start_matches('/').to_string()),
            );
        }
        Ok(pats)
    }

    /// Bytes-in → snapshot-out. Delegates to `svc_core::engine::snapshot_files`.
    pub(crate) fn snapshot_files(
        &self,
        files: &BTreeMap<RelPath, Vec<u8>>,
        prev: Option<&Snapshot>,
        change: ChangeId,
    ) -> Result<Snapshot> {
        // Files whose bytes are what `prev` rendered keep `prev`'s records when the tree's
        // definitions are unchanged: an absorb of one file no longer re-materializes all.
        let unchanged: std::collections::BTreeSet<RelPath> = match prev.and_then(|p| self.store.rendered_hashes(p.id()).ok().flatten()) {
            Some(hashes) => files
                .iter()
                .filter(|(path, bytes)| hashes.get(*path) == Some(blake3::hash(bytes).as_bytes()))
                .map(|(path, _)| path.clone())
                .collect(),
            None => Default::default(),
        };
        svc_core::engine::snapshot_files_reusing(&self.store, &self.langs, files, prev, change, &unchanged)
    }

    /// True when rendering the current snapshot reproduces the tracked files byte for byte.
    /// Does the tree on disk equal the current snapshot rendered? Every verb asks this first,
    /// so it hashes the tracked files against the snapshot's rendered hashes; a snapshot
    /// nobody has rendered yet is rendered once here and its hashes kept.
    pub fn working_copy_clean(&self) -> Result<bool> {
        let cur = self.current()?;
        let want = match self.store.rendered_hashes(cur.id())? {
            Some(h) => h,
            None => {
                let rendered = render(&cur, &self.store, &self.langs, false)?;
                let h = file_hashes(&rendered.files);
                self.store.set_rendered_hashes(cur.id(), &h)?;
                h
            }
        };
        let disk = self.tracked_files()?;
        Ok(disk.len() == want.len()
            && disk
                .iter()
                .all(|(p, b)| want.get(p) == Some(blake3::hash(b).as_bytes())))
    }

    /// Reconcile hand edits into the current change: re-snapshot
    /// the tracked files against the current snapshot, amend unless identical, and record an
    /// `Absorb` op whose `after.root` is the new snapshot (so O5 can replay it). Returns the
    /// previous snapshot and the new id when something was absorbed.
    pub fn absorb(&self) -> Result<Option<(Snapshot, SnapshotId)>> {
        if self.working_copy_clean()? {
            return Ok(None);
        }
        self.refuse_if_stale()?;
        let cur = self.current()?;
        let before = self.view()?;
        let (at, group, _) = self.stamp()?;
        // Staged before the re-snapshot, so its blobs ride in the one publish transaction
        // instead of one fsync each (2,265 entities: 20 s → 3 s).
        self.store.stage(Some(&before));
        let staged = (|| -> Result<Option<(SnapshotId, OpLogEntry)>> {
            let files = self.tracked_files()?;
            let next = self.snapshot_files(&files, Some(&cur), cur.change)?;
            if next.content_eq(&cur) {
                return Ok(None);
            }
            let id = self.amend(&cur, next)?;
            let after = self.view()?;
            Ok(Some((
                id,
                OpLogEntry {
                    op: Op::Absorb,
                    observed: None,
                    at,
                    group,
                    before,
                    after,
                },
            )))
        })();
        match staged {
            Ok(Some((id, entry))) => {
                self.append_op(&entry)?;
                Ok(Some((cur, id)))
            }
            Ok(None) => {
                self.store.discard_staged();
                Ok(None)
            }
            Err(error) => {
                self.store.discard_staged();
                Err(error)
            }
        }
    }

    /// Writes `snapshot`, points its change's head and `root` at it.
    pub fn commit_snapshot(&self, snapshot: &Snapshot) -> Result<SnapshotId> {
        let id = self.store.put_snapshot(snapshot)?;
        self.store.set_head(snapshot.change, id)?;
        self.store.set_root(id)?;
        Ok(id)
    }

    /// Rewrites the current change: `next` gets `cur` as its predecessor and inherits its
    /// parents. Identical content is a no-op and returns `cur`'s id.
    pub fn amend(&self, cur: &Snapshot, mut next: Snapshot) -> Result<SnapshotId> {
        let cur_id = cur.id();
        if next.content_eq(cur) {
            return Ok(cur_id);
        }
        next.parents = cur.parents.clone();
        next.predecessors = vec![cur_id];
        next.change = cur.change;
        self.commit_snapshot(&next)
    }

    /// Snapshot-before / commit / log / render-after, for every mutating verb.
    ///
    /// `f` receives the (absorbed) current snapshot and returns the snapshot the op yields,
    /// already wired (`parents`/`predecessors`/`change`) — use [`Repo::amend`] for rewrites
    /// of the current change or build a fresh one for `new`/`branch`.
    pub fn mutate(
        &self,
        op: Op,
        observed: Option<ObservedClass>,
        f: impl FnOnce(&Repo, &Snapshot) -> Result<SnapshotId>,
    ) -> Result<Mutation> {
        self.absorb()?;
        self.refuse_if_stale()?;
        let before = self.view()?;
        let (at, group, closed_stale_changeset) = self.stamp()?;
        let cur = self.current()?;
        // From here to `append_op`, head/root/render-pending writes are staged and land in
        // the op's own transaction: a crash never leaves the store a snapshot ahead of
        // the log, and a failing verb publishes nothing.
        self.store.stage(Some(&before));
        let staged = (|| -> Result<(SnapshotId, OpLogEntry)> {
            self.store.set_render_pending(true)?;
            let snapshot = f(self, &cur)?;
            let after = self.view()?;
            Ok((snapshot, OpLogEntry { op, observed, at, group, before, after }))
        })();
        let (snapshot, entry) = match staged {
            Ok(v) => v,
            Err(e) => {
                self.store.discard_staged();
                return Err(e);
            }
        };
        let ix = self.append_op(&entry)?;
        self.render_to_disk(&self.current()?)?;
        self.store.set_render_pending(false)?;
        Ok(Mutation {
            ix,
            entry,
            snapshot,
            closed_stale_changeset,
        })
    }

    /// Moves `root` and every head to `view`, records it as `op`, and re-renders.
    /// Heads absent from `view` cannot be removed through the `Store` API and stay behind.
    pub fn restore_view(&self, view: &View, op: Op) -> Result<Mutation> {
        self.absorb()?;
        let before = self.view()?;
        let (at, group, closed_stale_changeset) = self.stamp()?;
        self.store.stage(Some(&before));
        let staged = (|| -> Result<OpLogEntry> {
            self.store.set_render_pending(true)?;
            // Heads already where `view` wants them are neither written nor compared at
            // publish, so another checkout moving one of those meanwhile is not a conflict.
            for (change, snap) in &view.heads {
                if before.heads.get(change) != Some(snap) {
                    self.store.set_head(*change, *snap)?;
                }
            }
            self.store.set_root(view.root)?;
            let after = self.view()?;
            Ok(OpLogEntry { op, observed: None, at, group, before, after })
        })();
        let entry = match staged {
            Ok(e) => e,
            Err(e) => {
                self.store.discard_staged();
                return Err(e);
            }
        };
        let ix = self.append_op(&entry)?;
        self.render_to_disk(&self.current()?)?;
        self.store.set_render_pending(false)?;
        Ok(Mutation {
            ix,
            entry,
            snapshot: view.root,
            closed_stale_changeset,
        })
    }

    /// The open changeset to stamp on an op, closing a row whose owner is gone.
    pub fn open_group(&self) -> Result<(Option<ChangeSetId>, Option<ChangeSetId>)> {
        let Some(row) = self.store.open_changeset()? else {
            return Ok((None, None));
        };
        let alive = match row.pid {
            Some(pid) => Path::new("/proc").join(pid.to_string()).exists(),
            None => now().saturating_sub(row.opened_at) < CHANGESET_TTL_MS,
        };
        if alive {
            Ok((Some(row.id), None))
        } else {
            self.store.set_open_changeset(None)?;
            Ok((None, Some(row.id)))
        }
    }

    /// Writes every file of `snapshot` via temp + `rename(2)`, then deletes tracked files it
    /// no longer contains. Never touches untracked files.
    pub fn render_to_disk(&self, snapshot: &Snapshot) -> Result<()> {
        let tracked = self.tracked_files()?;
        let rendered = render(snapshot, &self.store, &self.langs, false)?.files;
        let removed = self.clear_render_obstructions(&rendered, &tracked)?;
        Self::write_rendered_files(&self.root, &rendered)?;
        for rel in tracked.keys() {
            let path = self.root.join(rel.as_str());
            if !rendered.contains_key(rel) && !removed.contains(&path) {
                std::fs::remove_file(path).map_err(Error::backend)?;
            }
        }
        // What was just written is what the next clean check compares against.
        self.store.set_rendered_hashes(snapshot.id(), &file_hashes(&rendered))?;
        Ok(())
    }

    /// The write half of [`Repo::render_to_disk`] aimed at any directory: every file of
    /// `snapshot` lands under `dir` (temp + `rename(2)`), nothing is deleted. Used to seed a
    /// new workspace. Returns what was rendered.
    pub(crate) fn render_into(
        &self,
        dir: &Path,
        snapshot: &Snapshot,
    ) -> Result<BTreeMap<RelPath, Vec<u8>>> {
        let rendered = render(snapshot, &self.store, &self.langs, false)?.files;
        Self::write_rendered_files(dir, &rendered)?;
        self.store.set_rendered_hashes(snapshot.id(), &file_hashes(&rendered))?;
        Ok(rendered)
    }

    fn clear_render_obstructions(
        &self,
        rendered: &BTreeMap<RelPath, Vec<u8>>,
        tracked: &BTreeMap<RelPath, Vec<u8>>,
    ) -> Result<BTreeSet<PathBuf>> {
        let obsolete: BTreeSet<_> = tracked.keys()
            .filter(|rel| !rendered.contains_key(*rel))
            .map(|rel| self.root.join(rel.as_str()))
            .collect();
        let mut files = BTreeSet::new();
        let mut dirs = BTreeSet::new();
        let obstruction = |path: &Path| Error::Other(format!(
            "untracked path obstructs render: {}", path.display()
        ));
        let kind = |path: &Path| match std::fs::symlink_metadata(path) {
            Ok(meta) => Ok(Some(meta.file_type())),
            Err(e) if matches!(e.kind(), ErrorKind::NotFound | ErrorKind::NotADirectory) => Ok(None),
            Err(e) => Err(Error::backend(e)),
        };
        for (rel, bytes) in rendered {
            let path = self.root.join(rel.as_str());
            for parent in path.ancestors().skip(1).take_while(|p| *p != self.root) {
                if kind(parent)?.is_some_and(|t| !t.is_dir()) {
                    if !obsolete.contains(parent) {
                        return Err(obstruction(parent));
                    }
                    files.insert(parent.to_path_buf());
                }
            }
            match kind(&path)? {
                Some(t) if t.is_dir() => {
                    let mut pending = vec![path];
                    while let Some(dir) = pending.pop() {
                        for entry in std::fs::read_dir(&dir).map_err(Error::backend)? {
                            let entry = entry.map_err(Error::backend)?;
                            let path = entry.path();
                            if entry.file_type().map_err(Error::backend)?.is_dir() {
                                pending.push(path);
                            } else if obsolete.contains(&path) {
                                files.insert(path);
                            } else {
                                return Err(obstruction(&path));
                            }
                        }
                        dirs.insert(dir);
                    }
                }
                Some(_) if !tracked.contains_key(rel)
                    && std::fs::read(&path).ok().as_deref() != Some(bytes.as_slice()) => {
                    return Err(obstruction(&path));
                }
                _ => {}
            }
        }
        for path in &files {
            std::fs::remove_file(path).map_err(Error::backend)?;
        }
        for path in dirs.iter().rev() {
            std::fs::remove_dir(path).map_err(|e| Error::Other(format!(
                "cannot clear render obstruction {}: {e}", path.display()
            )))?;
        }
        Ok(files)
    }

    fn write_rendered_files(dir: &Path, rendered: &BTreeMap<RelPath, Vec<u8>>) -> Result<()> {
        for (rel, bytes) in rendered {
            let path = dir.join(rel.as_str());
            if std::fs::read(&path).ok().as_deref() == Some(bytes.as_slice()) {
                continue;
            }
            let parent = path.parent().ok_or_else(|| Error::InvalidPath(rel.to_string()))?;
            std::fs::create_dir_all(parent).map_err(Error::backend)?;
            let mut tmp = tempfile::NamedTempFile::new_in(parent).map_err(Error::backend)?;
            tmp.write_all(bytes).map_err(Error::backend)?;
            if let Ok(meta) = std::fs::metadata(&path) {
                tmp.as_file().set_permissions(meta.permissions()).map_err(Error::backend)?;
            }
            tmp.persist(&path).map_err(Error::backend)?;
        }
        Ok(())
    }
}

fn file_hashes(files: &BTreeMap<RelPath, Vec<u8>>) -> BTreeMap<RelPath, [u8; 32]> {
    files.iter().map(|(p, b)| (p.clone(), *blake3::hash(b).as_bytes())).collect()
}

fn is_ignored(rel: &str, patterns: &[String]) -> bool {
    let name = rel.rsplit('/').next().unwrap_or(rel);
    patterns.iter().any(|p| {
        if p.contains('/') {
            rel == p || rel.starts_with(&format!("{p}/"))
        } else {
            name == p
        }
    })
}

pub fn now() -> Timestamp {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

//! A checked-out repository: the `.svc/` store plus the working copy around it.
//!
//! Every mutating verb goes through [`Repo::mutate`], which snapshots the working copy
//! before, commits, records the op, and renders after. Nothing here decides
//! what a snapshot *contains* — that is `svc_core::engine`'s job; this module only moves
//! bytes between disk and store and keeps `root`/`heads`/the op log consistent.

use std::collections::{BTreeMap, BTreeSet};
use std::fs::{File, OpenOptions};
use std::io::{ErrorKind, Write};
use std::path::{Path, PathBuf};
use std::sync::Mutex;
use std::time::{Duration, Instant, SystemTime, UNIX_EPOCH};

use svc_core::engine::render;
use svc_core::{
    CHANGESET_TTL_MS, ChangeId, ChangeSetId, Error, JsLang, Langs, ObservedClass, Op, OpIx,
    OpLogEntry, RelPath, Result, RustLang, Snapshot, SnapshotId, Store, Timestamp, View,
};

use crate::store::RedbStore;
use crate::workspace::{POINTER_FILE, WorkspacePointer};

pub const STORE_DIR: &str = ".svc";
pub const STORE_FILE: &str = "store.redb";
/// The store while `init` imports; renamed to [`STORE_FILE`] once the first op is in.
pub const STORE_FILE_IMPORTING: &str = "store.redb.importing";
pub const IGNORE_FILE: &str = ".svcignore";
/// Under `.svc/`: held (`flock`) by the one `Repo` open on the default checkout.
pub const CHECKOUT_LOCK: &str = "checkout.lock";

/// Directories never walked, on top of `.svcignore`.
const ALWAYS_IGNORED: &[&str] = &[
    STORE_DIR,
    ".git",
    ".jj",
    "target",
    "node_modules",
    POINTER_FILE,
];

/// How long `open` waits for another `svc` process to leave this checkout unless
/// `SVC_LOCK_TIMEOUT_MS` or [`Repo::open_with`] says otherwise.
///
/// The store is shared: any number of processes hold it open (redb `MultiWriter`), write
/// transactions serialise on the file, readers follow commits, and a publish that finds a
/// head or this checkout's root moved since the verb read them is refused with nothing
/// written (`append_op`). The working copy is not shared: one `Repo` per checkout at a
/// time, held by a lock on [`CHECKOUT_LOCK`] (a named checkout's pointer file doubles as
/// its lock), so two `svc` processes never render into one directory at once.
pub const DEFAULT_LOCK_TIMEOUT: Duration = Duration::from_secs(5);
pub const LOCK_TIMEOUT_ENV: &str = "SVC_LOCK_TIMEOUT_MS";

pub fn lock_timeout() -> Duration {
    std::env::var(LOCK_TIMEOUT_ENV)
        .ok()
        .and_then(|v| v.trim().parse::<u64>().ok())
        .map(Duration::from_millis)
        .unwrap_or(DEFAULT_LOCK_TIMEOUT)
}

pub struct Repo {
    root: PathBuf,
    store_path: PathBuf,
    pub(crate) store: RedbStore,
    langs: Langs,
    _checkout_lock: File,
    /// Set while a history is replayed: the op line takes the recorded time, changeset and
    /// checkout instead of now, the open changeset and this checkout.
    provenance: Mutex<Option<Provenance>>,
}

/// Where an op line came from, when it did not come from this process now.
#[derive(Clone, Debug)]
pub struct Provenance {
    pub at: Timestamp,
    pub group: Option<ChangeSetId>,
    /// The checkout that made it (`None` = the default one).
    pub workspace: Option<String>,
}

/// What `mutate` did, for the verb to print.
#[derive(Clone, Debug)]
pub struct Mutation {
    pub ix: OpIx,
    pub entry: OpLogEntry,
    /// The snapshot the op produced (equal to `entry.after.root` unless the op was a no-op).
    pub snapshot: SnapshotId,
    /// Set when a stale `open_changeset` row was closed on the way.
    pub closed_stale_changeset: Option<ChangeSetId>,
}

impl Repo {
    pub fn default_langs() -> Langs {
        Langs::new(vec![Box::new(RustLang), Box::new(JsLang)])
    }

    /// Nearest ancestor of `start` (inclusive) that is a checkout: it holds `.svc/store.redb`
    /// (the default checkout) or a `.svc-workspace` pointer (a named one).
    pub fn find_root(start: &Path) -> Option<PathBuf> {
        start
            .ancestors()
            .find(|p| Self::is_checkout(p))
            .map(Path::to_path_buf)
    }

    fn is_checkout(dir: &Path) -> bool {
        dir.join(STORE_DIR).join(STORE_FILE).is_file() || dir.join(POINTER_FILE).is_file()
    }

    /// Creates `.svc/` and the first snapshot from every tracked file. Refuses to re-init.
    ///
    /// The store is born as [`STORE_FILE_IMPORTING`] and renamed to [`STORE_FILE`] only after
    /// the first op has committed, so a killed or failed import never leaves a directory
    /// that looks like a checkout but has no root: until the rename it is not a checkout,
    /// and the next `init` sweeps the leftover.
    pub fn init(root: &Path, langs: Langs) -> Result<Self> {
        let dir = root.join(STORE_DIR);
        if dir.join(STORE_FILE).exists() {
            return Err(Error::Other(format!("{} already exists", dir.display())));
        }
        if root.join(POINTER_FILE).exists() {
            return Err(Error::Other(format!(
                "{} is already a workspace of another store",
                root.display()
            )));
        }
        std::fs::create_dir_all(&dir).map_err(Error::backend)?;
        let made = Self::first_import(root, &dir, langs);
        if made.is_err() {
            let _ = std::fs::remove_file(dir.join(STORE_FILE_IMPORTING));
            let _ = std::fs::remove_file(dir.join(CHECKOUT_LOCK));
            let _ = std::fs::remove_dir(&dir);
        }
        made
    }

    fn first_import(root: &Path, dir: &Path, langs: Langs) -> Result<Self> {
        let checkout_lock = Self::checkout_lock(&dir.join(CHECKOUT_LOCK), lock_timeout())?;
        let importing = dir.join(STORE_FILE_IMPORTING);
        // A previous init died mid-import; the lock says nobody is in it now.
        let _ = std::fs::remove_file(&importing);
        let store = RedbStore::create(&importing)?;
        let mut repo = Self {
            root: root.to_path_buf(),
            store_path: importing.clone(),
            store,
            langs,
            _checkout_lock: checkout_lock,
            provenance: Mutex::new(None),
        };
        let change = ChangeId::new();
        // Every blob and snapshot of the first import lands in the one transaction that
        // records the op: one fsync, and no half-imported store on a crash.
        repo.store.stage(None);
        let files = repo.tracked_files()?;
        let snapshot = repo.snapshot_files(&files, None, change)?;
        // The op log needs a "before"; an empty snapshot makes init blame as `Added`.
        let empty = repo.store.put_snapshot(&Snapshot {
            entities: BTreeMap::new(),
            files: BTreeMap::new(),
            ..snapshot.clone()
        })?;
        repo.commit_snapshot(&snapshot)?;
        let view = repo.view()?;
        repo.store.append_op(&OpLogEntry {
            op: Op::New { change },
            observed: None,
            at: now(),
            group: None,
            before: View {
                root: empty,
                heads: BTreeMap::new(),
            },
            after: view,
        })?;
        let store_path = dir.join(STORE_FILE);
        std::fs::rename(&importing, &store_path).map_err(Error::backend)?;
        repo.store_path = store_path;
        Ok(repo)
    }

    /// Opens an existing repo, waiting out another process on the same checkout, and finishes
    /// any render a crashed predecessor left pending.
    ///
    /// `root` is either the default checkout (holds `.svc/store.redb`) or a named workspace
    /// (holds a `.svc-workspace` pointer at the shared store).
    pub fn open(root: &Path, langs: Langs) -> Result<Self> {
        Self::open_with(root, langs, lock_timeout())
    }

    /// [`Repo::open`] with an explicit bound on how long to wait for another session on this
    /// checkout.
    pub fn open_with(root: &Path, langs: Langs, wait: Duration) -> Result<Self> {
        let own = root.join(STORE_DIR).join(STORE_FILE);
        let (store_path, workspace) = if own.is_file() {
            (own, None)
        } else if let Some(ptr) = WorkspacePointer::read(root)? {
            (ptr.store, Some(ptr.name))
        } else {
            return Err(Error::Other(format!("no {STORE_DIR} in {}", root.display())));
        };
        if !store_path.is_file() {
            return Err(Error::Other(format!(
                "{} points at a missing store {}",
                root.join(POINTER_FILE).display(),
                store_path.display()
            )));
        }
        let lock_path = match workspace {
            Some(_) => root.join(POINTER_FILE),
            None => root.join(STORE_DIR).join(CHECKOUT_LOCK),
        };
        let checkout_lock = Self::checkout_lock(&lock_path, wait)?;
        let store = RedbStore::open(&store_path)?.with_workspace(workspace.as_deref())?;
        // A store written before the current snapshot encoding does not decode; say so
        // rather than surfacing the decoder's complaint.
        if let Err(e) = store.root().and_then(|root| store.get_snapshot(root)) {
            return Err(Error::Other(format!(
                "{} was written by an older svc and cannot be read by this one ({e}); on a clean tree: rm -rf .svc && svc init (secondary checkouts: svc workspace add again)",
                store_path.display()
            )));
        }
        // A pointer names a workspace; only the directory the store registered for that
        // name is its working copy. Anything else opened as it would absorb its own files
        // into that change.
        if let Some(name) = &workspace {
            let registered = store.workspace_row(name)?.map(|r| r.path).unwrap_or_default();
            let here = root.canonicalize().map_err(Error::backend)?;
            if registered != here {
                return Err(Error::Other(format!(
                    "{} names workspace {name:?}, which is registered at {}; this directory is not that checkout",
                    root.join(POINTER_FILE).display(),
                    registered.display()
                )));
            }
        }
        let repo = Self {
            root: root.to_path_buf(),
            store_path,
            store,
            langs,
            _checkout_lock: checkout_lock,
            provenance: Mutex::new(None),
        };
        if repo.store.render_pending()? {
            repo.render_to_disk(&repo.current()?)?;
            repo.store.set_render_pending(false)?;
        }
        Ok(repo)
    }

    /// Takes the checkout's lock, polling up to `wait` while another `svc` holds it. The
    /// kernel drops it with the process, so a crash never leaves a checkout locked.
    fn checkout_lock(path: &Path, wait: Duration) -> Result<File> {
        let file = OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(false)
            .open(path)
            .map_err(Error::backend)?;
        let started = Instant::now();
        let mut backoff = Duration::from_millis(10);
        loop {
            match file.try_lock() {
                Ok(()) => return Ok(file),
                Err(std::fs::TryLockError::WouldBlock) => {
                    if started.elapsed() >= wait {
                        return Err(Error::Other(format!(
                            "checkout busy: another svc session held {} for {}ms (raise {LOCK_TIMEOUT_ENV})",
                            path.display(),
                            wait.as_millis()
                        )));
                    }
                    std::thread::sleep(backoff);
                    backoff = (backoff * 2).min(Duration::from_millis(250));
                }
                Err(std::fs::TryLockError::Error(e)) => return Err(Error::backend(e)),
            }
        }
    }

    /// True when this checkout's `root` is no longer its change's head — another checkout
    /// (or `svc checkout` of an older evolution) moved on. Mutating from here would silently
    /// overwrite that head, so [`Repo::mutate`] refuses until `workspace::update_stale`.
    pub fn is_stale(&self) -> Result<bool> {
        let cur = self.current()?;
        Ok(self.store.head(cur.change)? != cur.id())
    }

    fn refuse_if_stale(&self) -> Result<()> {
        if self.is_stale()? {
            let cur = self.current()?;
            return Err(Error::Other(format!(
                "checkout is behind change {}: its head moved to {} (run `svc workspace update-stale`, or `svc checkout` it)",
                cur.change.short(),
                self.store.head(cur.change)?.short()
            )));
        }
        Ok(())
    }

    pub fn discover(start: &Path, langs: Langs) -> Result<Self> {
        let Some(root) = Self::find_root(start) else {
            let unfinished = start
                .ancestors()
                .find(|p| p.join(STORE_DIR).join(STORE_FILE_IMPORTING).is_file());
            return Err(Error::Other(match unfinished {
                Some(p) => format!(
                    "{} holds an unfinished import (an svc init that did not finish); run svc init again",
                    p.join(STORE_DIR).display()
                ),
                None => format!("no {STORE_DIR} above {}", start.display()),
            }));
        };
        Self::open(&root, langs)
    }

    pub fn store(&self) -> &dyn Store {
        &self.store
    }

    /// The concrete store, for what the `Store` trait does not cover (workspaces, op attribution).
    /// Run `f` with every op it records stamped as `p` (a replayed history keeps its times,
    /// changesets and checkouts); cleared afterwards, also on error.
    pub fn with_provenance<T>(&self, p: Provenance, f: impl FnOnce() -> Result<T>) -> Result<T> {
        *self.provenance.lock().unwrap() = Some(p);
        let out = f();
        *self.provenance.lock().unwrap() = None;
        out
    }

    /// Time and changeset for the op line being written: the provenance if one is set, else
    /// now and the open changeset (closing a stale one on the way).
    fn stamp(&self) -> Result<(Timestamp, Option<ChangeSetId>, Option<ChangeSetId>)> {
        if let Some(p) = self.provenance.lock().unwrap().as_ref() {
            return Ok((p.at, p.group, None));
        }
        let (group, closed) = self.open_group()?;
        Ok((now(), group, closed))
    }

    fn append_op(&self, entry: &OpLogEntry) -> Result<OpIx> {
        let ws = self.provenance.lock().unwrap().as_ref().and_then(|p| p.workspace.clone());
        match ws {
            Some(w) => self.store.append_op_as(entry, Some(&w)),
            None if self.provenance.lock().unwrap().is_some() => self.store.append_op_as(entry, None),
            None => self.store.append_op(entry),
        }
    }

    pub fn redb(&self) -> &RedbStore {
        &self.store
    }

    pub fn root_dir(&self) -> &Path {
        &self.root
    }

    /// The shared `.svc/store.redb` this checkout reads, wherever the checkout itself lives.
    pub fn store_path(&self) -> &Path {
        &self.store_path
    }

    /// The named workspace this checkout is, or `None` for the default one.
    pub fn workspace(&self) -> Option<&str> {
        self.store.workspace()
    }

    pub fn langs(&self) -> &Langs {
        &self.langs
    }

    pub fn view(&self) -> Result<View> {
        Ok(View {
            root: self.store.root()?,
            heads: self.store.heads()?.into_iter().collect(),
        })
    }

    /// The working-copy snapshot and its id.
    pub fn current(&self) -> Result<Snapshot> {
        self.store.get_snapshot(self.store.root()?)
    }

    pub fn current_change(&self) -> Result<ChangeId> {
        Ok(self.current()?.change)
    }

    /// Branch name first, then unique change-id prefix.
    pub fn resolve_change(&self, s: &str) -> Result<ChangeId> {
        if let Some(id) = self.store.branch(s)? {
            return Ok(id);
        }
        self.store.resolve_prefix(s)
    }

    /// Every file under the root that is not ignored. Language files become entities;
    /// everything else is an opaque `FileRecord` (Cargo.toml, lockfiles, …) so a
    /// render of this repository is still a crate cargo can build.
    /// Regular files only: symlinks (dangling or not, to files or to directories), FIFOs,
    /// sockets and devices are not tracked — a store holds bytes, and reading a FIFO would
    /// block every verb.
    pub fn tracked_files(&self) -> Result<BTreeMap<RelPath, Vec<u8>>> {
        let ignore = self.ignore_patterns()?;
        let mut out = BTreeMap::new();
        let mut stack = vec![self.root.clone()];
        while let Some(dir) = stack.pop() {
            for entry in std::fs::read_dir(&dir).map_err(Error::backend)? {
                let entry = entry.map_err(Error::backend)?;
                let path = entry.path();
                let rel_os = path.strip_prefix(&self.root).map_err(|e| Error::Other(e.to_string()))?;
                let lossy = rel_os.to_string_lossy();
                if is_ignored(&lossy, &ignore) {
                    continue;
                }
                // A store path is a string; a name it cannot hold would come back changed
                // from a render, so it is refused here by name instead.
                let Some(rel) = rel_os.to_str().map(str::to_owned) else {
                    return Err(Error::InvalidPath(format!(
                        "{lossy}: file name is not UTF-8; rename it, or ignore its directory in {IGNORE_FILE}"
                    )));
                };
                let kind = entry.file_type().map_err(Error::backend)?;
                if kind.is_dir() {
                    stack.push(path);
                    continue;
                }
                if !kind.is_file() {
                    continue;
                }
                let rel = RelPath::new(rel).map_err(Error::InvalidPath)?;
                out.insert(rel, std::fs::read(&path).map_err(Error::backend)?);
            }
        }
        Ok(out)
    }

    fn ignore_patterns(&self) -> Result<Vec<String>> {
        let mut pats: Vec<String> = ALWAYS_IGNORED.iter().map(|s| s.to_string()).collect();
        if let Ok(text) = std::fs::read_to_string(self.root.join(IGNORE_FILE)) {
            pats.extend(
                text.lines()
                    .map(str::trim)
                    .filter(|l| !l.is_empty() && !l.starts_with('#'))
                    .map(|l| l.trim_end_matches('/').trim_start_matches('/').to_string()),
            );
        }
        Ok(pats)
    }

    /// Bytes-in → snapshot-out. Delegates to `svc_core::engine::snapshot_files`.
    pub(crate) fn snapshot_files(
        &self,
        files: &BTreeMap<RelPath, Vec<u8>>,
        prev: Option<&Snapshot>,
        change: ChangeId,
    ) -> Result<Snapshot> {
        // Files whose bytes are what `prev` rendered keep `prev`'s records when the tree's
        // definitions are unchanged: an absorb of one file no longer re-materializes all.
        let unchanged: std::collections::BTreeSet<RelPath> = match prev.and_then(|p| self.store.rendered_hashes(p.id()).ok().flatten()) {
            Some(hashes) => files
                .iter()
                .filter(|(path, bytes)| hashes.get(*path) == Some(blake3::hash(bytes).as_bytes()))
                .map(|(path, _)| path.clone())
                .collect(),
            None => Default::default(),
        };
        svc_core::engine::snapshot_files_reusing(&self.store, &self.langs, files, prev, change, &unchanged)
    }

    /// True when rendering the current snapshot reproduces the tracked files byte for byte.
    /// Does the tree on disk equal the current snapshot rendered? Every verb asks this first,
    /// so it hashes the tracked files against the snapshot's rendered hashes; a snapshot
    /// nobody has rendered yet is rendered once here and its hashes kept.
    pub fn working_copy_clean(&self) -> Result<bool> {
        let cur = self.current()?;
        let want = match self.store.rendered_hashes(cur.id())? {
            Some(h) => h,
            None => {
                let rendered = render(&cur, &self.store, &self.langs, false)?;
                let h = file_hashes(&rendered.files);
                self.store.set_rendered_hashes(cur.id(), &h)?;
                h
            }
        };
        let disk = self.tracked_files()?;
        Ok(disk.len() == want.len()
            && disk
                .iter()
                .all(|(p, b)| want.get(p) == Some(blake3::hash(b).as_bytes())))
    }

    /// Reconcile hand edits into the current change: re-snapshot
    /// the tracked files against the current snapshot, amend unless identical, and record an
    /// `Absorb` op whose `after.root` is the new snapshot (so O5 can replay it). Returns the
    /// previous snapshot and the new id when something was absorbed.
    pub fn absorb(&self) -> Result<Option<(Snapshot, SnapshotId)>> {
        if self.working_copy_clean()? {
            return Ok(None);
        }
        self.refuse_if_stale()?;
        let cur = self.current()?;
        let before = self.view()?;
        let (at, group, _) = self.stamp()?;
        // Staged before the re-snapshot, so its blobs ride in the one publish transaction
        // instead of one fsync each (2,265 entities: 20 s → 3 s).
        self.store.stage(Some(&before));
        let staged = (|| -> Result<Option<(SnapshotId, OpLogEntry)>> {
            let files = self.tracked_files()?;
            let next = self.snapshot_files(&files, Some(&cur), cur.change)?;
            if next.content_eq(&cur) {
                return Ok(None);
            }
            let id = self.amend(&cur, next)?;
            let after = self.view()?;
            Ok(Some((
                id,
                OpLogEntry {
                    op: Op::Absorb,
                    observed: None,
                    at,
                    group,
                    before,
                    after,
                },
            )))
        })();
        match staged {
            Ok(Some((id, entry))) => {
                self.append_op(&entry)?;
                Ok(Some((cur, id)))
            }
            Ok(None) => {
                self.store.discard_staged();
                Ok(None)
            }
            Err(error) => {
                self.store.discard_staged();
                Err(error)
            }
        }
    }

    /// Writes `snapshot`, points its change's head and `root` at it.
    pub fn commit_snapshot(&self, snapshot: &Snapshot) -> Result<SnapshotId> {
        let id = self.store.put_snapshot(snapshot)?;
        self.store.set_head(snapshot.change, id)?;
        self.store.set_root(id)?;
        Ok(id)
    }

    /// Rewrites the current change: `next` gets `cur` as its predecessor and inherits its
    /// parents. Identical content is a no-op and returns `cur`'s id.
    pub fn amend(&self, cur: &Snapshot, mut next: Snapshot) -> Result<SnapshotId> {
        let cur_id = cur.id();
        if next.content_eq(cur) {
            return Ok(cur_id);
        }
        next.parents = cur.parents.clone();
        next.predecessors = vec![cur_id];
        next.change = cur.change;
        self.commit_snapshot(&next)
    }

    /// Snapshot-before / commit / log / render-after, for every mutating verb.
    ///
    /// `f` receives the (absorbed) current snapshot and returns the snapshot the op yields,
    /// already wired (`parents`/`predecessors`/`change`) — use [`Repo::amend`] for rewrites
    /// of the current change or build a fresh one for `new`/`branch`.
    pub fn mutate(
        &self,
        op: Op,
        observed: Option<ObservedClass>,
        f: impl FnOnce(&Repo, &Snapshot) -> Result<SnapshotId>,
    ) -> Result<Mutation> {
        self.absorb()?;
        self.refuse_if_stale()?;
        let before = self.view()?;
        let (at, group, closed_stale_changeset) = self.stamp()?;
        let cur = self.current()?;
        // From here to `append_op`, head/root/render-pending writes are staged and land in
        // the op's own transaction: a crash never leaves the store a snapshot ahead of
        // the log, and a failing verb publishes nothing.
        self.store.stage(Some(&before));
        let staged = (|| -> Result<(SnapshotId, OpLogEntry)> {
            self.store.set_render_pending(true)?;
            let snapshot = f(self, &cur)?;
            let after = self.view()?;
            Ok((snapshot, OpLogEntry { op, observed, at, group, before, after }))
        })();
        let (snapshot, entry) = match staged {
            Ok(v) => v,
            Err(e) => {
                self.store.discard_staged();
                return Err(e);
            }
        };
        let ix = self.append_op(&entry)?;
        self.render_to_disk(&self.current()?)?;
        self.store.set_render_pending(false)?;
        Ok(Mutation {
            ix,
            entry,
            snapshot,
            closed_stale_changeset,
        })
    }

    /// Moves `root` and every head to `view`, records it as `op`, and re-renders.
    /// Heads absent from `view` cannot be removed through the `Store` API and stay behind.
    pub fn restore_view(&self, view: &View, op: Op) -> Result<Mutation> {
        self.absorb()?;
        let before = self.view()?;
        let (at, group, closed_stale_changeset) = self.stamp()?;
        self.store.stage(Some(&before));
        let staged = (|| -> Result<OpLogEntry> {
            self.store.set_render_pending(true)?;
            // Heads already where `view` wants them are neither written nor compared at
            // publish, so another checkout moving one of those meanwhile is not a conflict.
            for (change, snap) in &view.heads {
                if before.heads.get(change) != Some(snap) {
                    self.store.set_head(*change, *snap)?;
                }
            }
            self.store.set_root(view.root)?;
            let after = self.view()?;
            Ok(OpLogEntry { op, observed: None, at, group, before, after })
        })();
        let entry = match staged {
            Ok(e) => e,
            Err(e) => {
                self.store.discard_staged();
                return Err(e);
            }
        };
        let ix = self.append_op(&entry)?;
        self.render_to_disk(&self.current()?)?;
        self.store.set_render_pending(false)?;
        Ok(Mutation {
            ix,
            entry,
            snapshot: view.root,
            closed_stale_changeset,
        })
    }

    /// The open changeset to stamp on an op, closing a row whose owner is gone.
    pub fn open_group(&self) -> Result<(Option<ChangeSetId>, Option<ChangeSetId>)> {
        let Some(row) = self.store.open_changeset()? else {
            return Ok((None, None));
        };
        let alive = match row.pid {
            Some(pid) => Path::new("/proc").join(pid.to_string()).exists(),
            None => now().saturating_sub(row.opened_at) < CHANGESET_TTL_MS,
        };
        if alive {
            Ok((Some(row.id), None))
        } else {
            self.store.set_open_changeset(None)?;
            Ok((None, Some(row.id)))
        }
    }

    /// Writes every file of `snapshot` via temp + `rename(2)`, then deletes tracked files it
    /// no longer contains. Never touches untracked files.
    pub fn render_to_disk(&self, snapshot: &Snapshot) -> Result<()> {
        let tracked = self.tracked_files()?;
        let rendered = render(snapshot, &self.store, &self.langs, false)?.files;
        let removed = self.clear_render_obstructions(&rendered, &tracked)?;
        Self::write_rendered_files(&self.root, &rendered)?;
        for rel in tracked.keys() {
            let path = self.root.join(rel.as_str());
            if !rendered.contains_key(rel) && !removed.contains(&path) {
                std::fs::remove_file(path).map_err(Error::backend)?;
            }
        }
        // What was just written is what the next clean check compares against.
        self.store.set_rendered_hashes(snapshot.id(), &file_hashes(&rendered))?;
        Ok(())
    }

    /// The write half of [`Repo::render_to_disk`] aimed at any directory: every file of
    /// `snapshot` lands under `dir` (temp + `rename(2)`), nothing is deleted. Used to seed a
    /// new workspace. Returns what was rendered.
    pub(crate) fn render_into(
        &self,
        dir: &Path,
        snapshot: &Snapshot,
    ) -> Result<BTreeMap<RelPath, Vec<u8>>> {
        let rendered = render(snapshot, &self.store, &self.langs, false)?.files;
        Self::write_rendered_files(dir, &rendered)?;
        self.store.set_rendered_hashes(snapshot.id(), &file_hashes(&rendered))?;
        Ok(rendered)
    }

    fn clear_render_obstructions(
        &self,
        rendered: &BTreeMap<RelPath, Vec<u8>>,
        tracked: &BTreeMap<RelPath, Vec<u8>>,
    ) -> Result<BTreeSet<PathBuf>> {
        let obsolete: BTreeSet<_> = tracked.keys()
            .filter(|rel| !rendered.contains_key(*rel))
            .map(|rel| self.root.join(rel.as_str()))
            .collect();
        let mut files = BTreeSet::new();
        let mut dirs = BTreeSet::new();
        let obstruction = |path: &Path| Error::Other(format!(
            "untracked path obstructs render: {}", path.display()
        ));
        let kind = |path: &Path| match std::fs::symlink_metadata(path) {
            Ok(meta) => Ok(Some(meta.file_type())),
            Err(e) if matches!(e.kind(), ErrorKind::NotFound | ErrorKind::NotADirectory) => Ok(None),
            Err(e) => Err(Error::backend(e)),
        };
        for (rel, bytes) in rendered {
            let path = self.root.join(rel.as_str());
            for parent in path.ancestors().skip(1).take_while(|p| *p != self.root) {
                if kind(parent)?.is_some_and(|t| !t.is_dir()) {
                    if !obsolete.contains(parent) {
                        return Err(obstruction(parent));
                    }
                    files.insert(parent.to_path_buf());
                }
            }
            match kind(&path)? {
                Some(t) if t.is_dir() => {
                    let mut pending = vec![path];
                    while let Some(dir) = pending.pop() {
                        for entry in std::fs::read_dir(&dir).map_err(Error::backend)? {
                            let entry = entry.map_err(Error::backend)?;
                            let path = entry.path();
                            if entry.file_type().map_err(Error::backend)?.is_dir() {
                                pending.push(path);
                            } else if obsolete.contains(&path) {
                                files.insert(path);
                            } else {
                                return Err(obstruction(&path));
                            }
                        }
                        dirs.insert(dir);
                    }
                }
                Some(_) if !tracked.contains_key(rel)
                    && std::fs::read(&path).ok().as_deref() != Some(bytes.as_slice()) => {
                    return Err(obstruction(&path));
                }
                _ => {}
            }
        }
        for path in &files {
            std::fs::remove_file(path).map_err(Error::backend)?;
        }
        for path in dirs.iter().rev() {
            std::fs::remove_dir(path).map_err(|e| Error::Other(format!(
                "cannot clear render obstruction {}: {e}", path.display()
            )))?;
        }
        Ok(files)
    }

    fn write_rendered_files(dir: &Path, rendered: &BTreeMap<RelPath, Vec<u8>>) -> Result<()> {
        for (rel, bytes) in rendered {
            let path = dir.join(rel.as_str());
            if std::fs::read(&path).ok().as_deref() == Some(bytes.as_slice()) {
                continue;
            }
            let parent = path.parent().ok_or_else(|| Error::InvalidPath(rel.to_string()))?;
            std::fs::create_dir_all(parent).map_err(Error::backend)?;
            let mut tmp = tempfile::NamedTempFile::new_in(parent).map_err(Error::backend)?;
            tmp.write_all(bytes).map_err(Error::backend)?;
            if let Ok(meta) = std::fs::metadata(&path) {
                tmp.as_file().set_permissions(meta.permissions()).map_err(Error::backend)?;
            }
            tmp.persist(&path).map_err(Error::backend)?;
        }
        Ok(())
    }
}

fn file_hashes(files: &BTreeMap<RelPath, Vec<u8>>) -> BTreeMap<RelPath, [u8; 32]> {
    files.iter().map(|(p, b)| (p.clone(), *blake3::hash(b).as_bytes())).collect()
}

fn is_ignored(rel: &str, patterns: &[String]) -> bool {
    let name = rel.rsplit('/').next().unwrap_or(rel);
    patterns.iter().any(|p| {
        if p.contains('/') {
            rel == p || rel.starts_with(&format!("{p}/"))
        } else {
            name == p
        }
    })
}

pub fn now() -> Timestamp {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_millis() as u64)
        .unwrap_or(0)
}

